const catalog=window.MOOKET_CATALOG;
const slug=id=>id.replace('/items/',''),en=id=>slug(id).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),name=id=>catalog.items[id]?.name||'新增物品（翻譯待更新）';
