const date=(n,short=false)=>new Date(n*1000).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',...(short?{}:{year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})});
let market={},timestamp=0,selected=[],days=3,mode='price',metric='p',variant='0',favorites=new Set(),onlyFav=false,histories=new Map(),view=[],generation=0,historyEnd=0;
try{favorites=new Set(JSON.parse(localStorage.getItem('mooket-favorites')||'[]'))}catch{}
