function quote(id){return market[id]?.[variant]||{}}
function icon(id){const src=catalog.items[id]?.icon;return src?`<img class="gameItemIcon" src="${esc(src)}" width="32" height="32" loading="lazy" decoding="async" alt="" aria-hidden="true">`:`<span class="iconFallback" aria-hidden="true">${esc(name(id).slice(0,1))}</span>`}
let page=1,pageSize=5,filteredIds=[];
let workspaceRestored=false;
const workspaceKey='mooket-workspace-v1';
function restoreWorkspace(){
 if(workspaceRestored)return;workspaceRestored=true;
 let raw=null;try{raw=localStorage.getItem(workspaceKey)}catch{}
 if(!raw&&typeof location!=='undefined'&&location.hash.startsWith('#workspace=')){try{raw=decodeURIComponent(location.hash.slice(11))}catch{}}
 let state;try{state=JSON.parse(raw||'null')}catch{return}
 if(!state||typeof state!=='object')return;
 if(Array.isArray(state.selected))selected=[...new Set(state.selected.filter(id=>typeof id==='string'&&/^\/items\/[a-z0-9_]+$/.test(id)))].slice(0,MAX_COMPARE);
 onlyFav=state.onlyFav===true;
 if(['detail','compare'].includes(state.chartStyle))chartStyle=state.chartStyle;
 if([5,20,50,100].includes(state.pageSize)){pageSize=state.pageSize;$('#pageSize').value=String(pageSize)}
 if(Number.isInteger(state.page)&&state.page>0&&state.page<=10000)page=state.page;
 for(const id of ['search','maxLevel','minVolume'])if(typeof state[id]==='string')$('#'+id).value=state[id].slice(0,100);
 for(const [id,values] of [['scope',['output','related']],['sort',['game','name','volumeDesc','bidDesc','priceAsc','priceDesc']]])if(values.includes(state[id]))$('#'+id).value=state[id];
 if(state.category==='all'||state.category in catalog.categories)$('#category').value=state.category;
 for(const id of ['excludeEquipment','excludeCharms'])$('#'+id).checked=state[id]===true;
}
function saveWorkspace(){
 if(!workspaceRestored)return;
 const encoded=JSON.stringify({selected,onlyFav,chartStyle,page,pageSize,search:$('#search').value,category:$('#category').value,scope:$('#scope').value,sort:$('#sort').value,maxLevel:$('#maxLevel').value,minVolume:$('#minVolume').value,excludeEquipment:$('#excludeEquipment').checked,excludeCharms:$('#excludeCharms').checked});
 try{localStorage.setItem(workspaceKey,encoded);if(localStorage.getItem(workspaceKey)===encoded){if(typeof location!=='undefined'&&location.hash.startsWith('#workspace='))window.history.replaceState(null,'',location.pathname+location.search);return}}catch{}
 // URL fragment stays in this browser and survives refresh when storage is blocked.
 try{window.history.replaceState(null,'',location.pathname+location.search+'#workspace='+encodeURIComponent(encoded))}catch{}
}

const processing=['coinify','decompose','transmute','enhancing'];
function actionMap(id){const m=catalog.items[id];return $('#scope').value==='related'?(m?.professions||{general:[]}):(m?.actions||{general:null})}
function matchesCategory(id,c){if(c==='all')return true;if(processing.includes(c))return c in professions(id);return c in actionMap(id)}
function actionText(id){let cat=$('#category').value;if(cat!=='all')return catalog.categories[cat];return Object.keys(actionMap(id)).map(c=>catalog.categories[c]).join('、')||'其他'}
function setupCategories(){const select=$('#category'),current=select.value;select.innerHTML='<option value="all">全部動作</option>'+Object.entries(catalog.categories).map(([key,label])=>`<option value="${key}">${label}（${Object.keys(market).filter(id=>matchesCategory(id,key)).length}）</option>`).join('');select.value=current||'all';$('#professionNav').innerHTML=Object.entries(catalog.categories).map(([key,label])=>`<button data-category="${key}" class="profession-link ${select.value===key?'active':''}" aria-pressed="${select.value===key}"><span>${label}</span><small>${Object.keys(market).filter(id=>matchesCategory(id,key)).length}</small></button>`).join('')}
function renderList(){let search=$('#search').value.trim().toLowerCase(),cat=$('#category').value,maxLevel=$('#maxLevel').value,minVolume=$('#minVolume').value,excludeEquip=$('#excludeEquipment').checked,excludeCharms=$('#excludeCharms').checked;
let ids=Object.keys(market).filter(id=>{let m=catalog.items[id]||{};return(!onlyFav||favorites.has(id))&&(!search||(name(id)+' '+en(id)+' '+id).toLowerCase().includes(search))&&matchesCategory(id,cat)&&(!excludeEquip||m.itemType!=='equipment')&&(!excludeCharms||!id.includes('_charm'))&&(maxLevel===''||(Number.isFinite(m.itemLevel)&&m.itemLevel<=+maxLevel))&&(minVolume===''||(Number.isFinite(quote(id).v)&&quote(id).v>=+minVolume))});
let sort=$('#sort').value;ids.sort((a,b)=>{if(sort==='name')return name(a).localeCompare(name(b),'zh-Hant');if(sort==='game')return (catalog.items[a]?.sortIndex||10000)-(catalog.items[b]?.sortIndex||10000);let key=sort==='volumeDesc'?'v':sort==='bidDesc'?'b':'a',va=quote(a)[key],vb=quote(b)[key],ok=n=>Number.isFinite(n)&&(key==='v'?n>=0:n>0);if(!ok(va))return !ok(vb)?0:1;if(!ok(vb))return-1;return(va-vb)*(sort==='priceAsc'?1:-1)});ids=scannerList(ids);filteredIds=ids;const pages=Math.max(1,Math.ceil(ids.length/pageSize));page=Math.max(1,Math.min(page,pages));let shown=ids.slice((page-1)*pageSize,page*pageSize);
$('#count').textContent=ids.length+' 項';$('#favcount').textContent=favorites.size;$('#listtitle').textContent=scannerActive?'漲跌幅篩選':onlyFav?'我的收藏':'市場物品';$('#allnav').classList.toggle('active',!onlyFav&&!scannerActive);$('#favnav').classList.toggle('active',onlyFav&&!scannerActive);setupCategories();
$('#items').innerHTML=shown.length?shown.map(id=>{let meta=catalog.items[id],lv=cat==='all'?Math.min(...Object.values(meta?.actions||{}).filter(v=>Number.isFinite(v))):meta?.actions?.[cat];if($('#scope').value==='related'||processing.includes(cat))lv=null;return `<tr class="item ${selected.includes(id)?'selected':''}"><td><button class="add" data-add="${esc(id)}" aria-pressed="${selected.includes(id)}" aria-label="${selected.includes(id)?'移除':'加入'}比較 ${esc(name(id))}">${selected.includes(id)?'✓':'＋'}</button></td><td><button class="name" data-select="${esc(id)}" title="${esc(en(id))}"><span class="itemicon">${icon(id)}</span><span>${esc(name(id))}<small>物品等級 ${Number.isFinite(meta?.itemLevel)?meta.itemLevel:'—'}</small></span></button></td>${scanCell(id)}<td><span class="actiontag">${esc(actionText(id))}</span></td><td>${Number.isFinite(lv)?lv:'—'}</td><td class="askprice">${fmt(quote(id).a)}</td><td>${fmt(quote(id).b)}</td><td>${fmt(quote(id).p)}</td><td>${Number.isFinite(quote(id).v)&&quote(id).v>=0?quote(id).v.toLocaleString():'—'}</td><td><button class="historylink" data-select="${esc(id)}">走勢 ↗</button></td><td><button class="star" data-star="${esc(id)}" aria-label="${favorites.has(id)?'取消收藏':'收藏'} ${esc(name(id))}">${favorites.has(id)?'★':'☆'}</button></td></tr>`}).join(''):'<tr><td colspan="11"><div class="empty">'+(scannerActive?'尚無符合門檻的已掃描物品。請開始掃描或調整篩選。':'沒有符合的物品。請調整篩選，或按「重設篩選」。')+'</div></td></tr>';
$('#pageSummary').textContent=`共 ${ids.length} 項 · 顯示 ${ids.length?(page-1)*pageSize+1:0}–${Math.min(page*pageSize,ids.length)}`;$('#pageNumber').textContent=`${page} / ${pages}`;$('#prevPage').disabled=page<=1;$('#nextPage').disabled=page>=pages;
$('#categoryHint').textContent=processing.includes(cat)?(cat==='enhancing'?'強化：列出強化材料與專用工具。':'煉金動作：列出可進行此動作的物品，非該動作產出。'):$('#scope').value==='related'?'相關用途：包含投入材料、額外掉落、工具與專業用品；同一物品可跨專業。':'主要產出：依採集／製作動作分類，不混入投入材料、額外掉落或專用工具。';
$('#selectedCount').textContent=selected.length;$('#total').textContent=Object.keys(market).length.toLocaleString();$('#quotes').textContent=Object.keys(market).filter(id=>valid(quote(id).a)).length.toLocaleString();saveWorkspace();}

function renderChips(){$('#chips').innerHTML=selected.map((id,i)=>`<span class="chip"><i style="background:${colors[i]}"></i>${icon(id)}${esc(name(id))}<button data-remove="${esc(id)}" aria-label="移除 ${esc(name(id))}">×</button></span>`).join('');$('#export').disabled=!selected.length}
async function q7Json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000),headers:{accept:'application/json'}});if(!r.ok)throw Error('Q7 HTTP '+r.status);const bytes=await r.arrayBuffer();try{return JSON.parse(new TextDecoder().decode(bytes))}catch{}for(const encoding of ['gzip','deflate','deflate-raw']){try{const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream(encoding));return JSON.parse(await new Response(stream).text())}catch{}}throw Error('Q7 data could not be decoded')}
async function history(id,period=days,level=variant){const requestDays=period===0?365:Math.ceil(period),key=id+':'+level+':'+requestDays,old=histories.get(key);if(old&&Date.now()-old.fetchedAt<600000)return old;let result;
try{const params=new URLSearchParams({item_id:id,variant:level,days:String(requestDays)}),data=await q7Json('https://q7.nainai.eu.org/api/market/histories?'+params);const rows=data[id]?.[level];if(!Array.isArray(rows))throw Error('Q7 schema');result={rows:window.MOOKET_TRADES.uniqueHours(rows),source:'q7',offline:false}}catch{try{const h=await json(BASE+'items_'+slug(id)+'__'+level+'.json');if(!Array.isArray(h.rows))throw Error('format');result={rows:h.rows,source:'archive',offline:false}}catch{if(level==='0'&&['milk','verdant_milk','holy_milk'].includes(slug(id))){try{const h=await json('history/'+slug(id)+'.json');if(!Array.isArray(h.rows))throw Error('format');result={rows:h.rows,source:'backup',offline:true}}catch{result={rows:[],source:'unavailable',error:true}}}else result={rows:[],source:'unavailable',error:true}}}
result.fetchedAt=Date.now();if(!result.error)histories.set(key,result);return result}
async function renderAnalysis(){renderChips();view=[];detailModel=null;detailActivate=null;$('#detailStats').innerHTML='';$('#tradeStats').innerHTML='';$('#detailReadout').textContent='讀取歷史樣本中…';$('#recordRows').innerHTML='';$('#export').disabled=true;let gen=++generation;$('#tooltip').hidden=true;$('#chart').innerHTML='<div class="empty">正在讀取歷史資料…</div>';$('#comparison').innerHTML='';$('#historynote').textContent='';let ids=[...selected];let results=await Promise.all(ids.map(id=>history(id)));if(gen!==generation)return;let now=Date.now()/1000;let end=Math.max(timestamp||0,...results.flatMap(x=>x.rows.filter(r=>Number.isFinite(r.time)&&r.time<=now).map(r=>r.time)));if(!end)end=now;historyEnd=end;let start=days?end-days*86400:end-365*86400;
view=ids.map((id,i)=>({id,color:colors[i],...results[i],stats:window.MOOKET_TRADES.summarize(results[i].rows,start,end,results[i].source),rows:results[i].rows.filter(r=>Number.isFinite(r.time)&&r.time>start&&r.time<=end).sort((a,b)=>a.time-b.time)}));draw();renderCompare();$('#export').disabled=!view.some(x=>x.rows.length);let failures=view.filter(x=>x.error).map(x=>name(x.id));let rows=view.flatMap(x=>x.rows),min=Math.min(...rows.map(x=>x.time)),max=Math.max(...rows.map(x=>x.time));$('#historynote').textContent=(rows.length?`歷史範圍 ${date(min)} — ${date(max)} · ${view.reduce((a,x)=>a+x.rows.length,0)} 筆樣本。`:'所選期間沒有歷史資料。')+(view.some(x=>x.offline)?' 部分使用建站時備份，非最新歷史。':'')+(failures.length?' 無法取得：'+failures.join('、')+'；可按更新重試。':'')+' 統計截至 '+date(end)+'。'+(view.some(x=>x.source==='q7')?' Q7 每小時歷史記錄。':'')+(view.some(x=>x.source!=='q7')?' 部分使用歷史快照備援，無法確認區間成交量。':'')+' 缺漏及超過 48 小時的間隔不連線。';}
function points(x){return x.rows.filter(r=>valid(r[metric]))}
function renderCompare(){$('#comparison').innerHTML=view.map(x=>{let p=points(x),change=p.length>1?(p.at(-1)[metric]/p[0][metric]-1)*100:null;return `<tr><td><span class="compareItemName"><i style="background:${x.color}"></i>${icon(x.id)}${esc(name(x.id))}</span></td><td>${fmt(quote(x.id)[metric])}</td><td class="${change===null?'':change>=0?'positive':'negative'}">${change===null?'資料不足':(change>0?'+':'')+change.toFixed(2)+'%'}</td><td>${p.length?fmt(Math.min(...p.map(r=>r[metric]))):'—'}</td><td>${p.length?fmt(Math.max(...p.map(r=>r[metric]))):'—'}</td></tr>`}).join('')||'<tr><td colspan="5">從左側選擇想觀察的素材。</td></tr>'}
function draw(){syncChartStyle();renderTradeStats();if(chartStyle==='detail')drawDetailed();else drawComparisonCharts()}
async function load(){let btn=$('#refresh');btn.disabled=true;$('#status').textContent='正在向官方 API 更新市場快照…';let data,source='官方 API';try{data=await json(OFFICIAL);if(!data.marketData||!data.timestamp)throw Error('invalid')}catch{try{data=await json('https://Iceking233.github.io/mwi-market-data/market/api.json');if(!data.marketData)throw Error('invalid');source='社群鏡像'}catch{data=await json('latest.json');source='建站時備份'}}market=data.marketData;timestamp=data.timestamp;setupCategories();restoreWorkspace();$('#updated').textContent=date(timestamp);let stale=Date.now()/1000-timestamp>86400;$('#status').textContent=`${source} · ${stale?'資料超過 24 小時，請留意時間。':'已載入市場快照。'} 買賣報價並非即時成交價格。`;$('#status').classList.toggle('warning',stale||source!=='官方 API');renderList();await renderAnalysis();btn.disabled=false}
$('#items').onclick=e=>{let el=e.target.closest('button');if(!el)return;let id=el.dataset.star;if(id){favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('mooket-favorites',JSON.stringify([...favorites]))}catch{}renderList();return}id=el.dataset.select;if(id){selected=[id];focusItem=id;recordPage=1;chartStyle='detail';$('#chartStyle').querySelectorAll('button').forEach(b=>{b.classList.toggle('on',b.dataset.style==='detail');b.setAttribute('aria-pressed',String(b.dataset.style==='detail'))});$('.analysis').scrollIntoView({behavior:'smooth',block:'start'})}id=el.dataset.add;if(id){if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<MAX_COMPARE)selected.push(id);else{$('#status').textContent='最多可比較 10 項，請先移除一個品項。';return}}renderList();renderAnalysis()};
$('#chips').onclick=e=>{let id=e.target.dataset.remove;if(id){selected=selected.filter(x=>x!==id);renderList();renderAnalysis()}};
const filterChanged=()=>{page=1;renderList()};$('#search').oninput=filterChanged;$('#category').onchange=filterChanged;$('#sort').onchange=filterChanged;for(const id of ['#scope','#maxLevel','#minVolume','#excludeEquipment','#excludeCharms'])$(id).onchange=filterChanged;$('#pageSize').onchange=e=>{pageSize=+e.target.value;page=1;renderList()};$('#prevPage').onclick=()=>{page--;renderList()};$('#nextPage').onclick=()=>{page++;renderList()};$('#professionNav').onclick=e=>{let key=e.target.closest('button')?.dataset.category;if(key){$('#category').value=key;onlyFav=false;filterChanged()}};$('.markettable thead').onclick=e=>{let sort=e.target.dataset.sort;if(sort){$('#sort').value=sort;filterChanged()}};$('#jumpChart').onclick=()=>$('.analysis').scrollIntoView({behavior:'smooth'});$('#resetFilters').onclick=()=>{for(const id of ['#search','#maxLevel','#minVolume'])$(id).value='';$('#category').value='all';$('#scope').value='output';$('#sort').value='game';$('#excludeEquipment').checked=false;$('#excludeCharms').checked=false;onlyFav=false;filterChanged()};$('#allnav').onclick=()=>{scannerActive=false;onlyFav=false;$('#category').value='all';page=1;renderList()};$('#favnav').onclick=()=>{scannerActive=false;onlyFav=true;page=1;renderList()};
$('#ranges').onclick=e=>{if(e.target.dataset.days===undefined)return;days=+e.target.dataset.days;$('#ranges').querySelectorAll('button').forEach(b=>b.classList.toggle('on',b===e.target));renderAnalysis()};$('#modes').onclick=e=>{if(!e.target.dataset.mode)return;mode=e.target.dataset.mode;$('#modes').querySelectorAll('button').forEach(b=>b.classList.toggle('on',b===e.target));draw()};$('#metric').onchange=e=>{metric=e.target.value;draw();renderCompare()};$('#variant').onchange=e=>{variant=e.target.value;renderList();renderAnalysis()};$('#refresh').onclick=()=>{histories.clear();load().catch(fail)};
$('#export').onclick=()=>{if(!view.some(x=>x.rows.length)){$('#status').textContent='目前沒有可匯出的歷史資料。';return}const rows=[['item_id','item_name','enhancement','unix_time','time_Asia_Taipei','ask','bid','average_price','volume_source_period','history_source'],...view.flatMap(x=>x.rows.map(r=>[x.id,name(x.id),variant,r.time,date(r.time),valid(r.a)?r.a:'',valid(r.b)?r.b:'',valid(r.p)?r.p:'',window.MOOKET_CHART.volume(r.v)?r.v:'',x.source]))];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='mooket-history.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
function fail(e){$('#status').textContent='暫時無法載入市場資料，請按「更新」重試。';$('#status').classList.add('warning');$('#refresh').disabled=false;console.error(e)}
document.addEventListener('error',event=>{const image=event.target;if(image?.classList?.contains('gameItemIcon')){const fallback=document.createElement('span');fallback.className='iconFallback';fallback.textContent='◈';fallback.setAttribute('aria-hidden','true');image.replaceWith(fallback)}},true);
setupCategories();restoreWorkspace();initDetailChart();initScanner();load().catch(fail);setInterval(()=>{histories.clear();load().catch(fail)},65*60*1000);
